mapper.select:
SELECT * FROM tCodConstrVal
AND ConstrCode = #{pConstrCode}
AND ConstrVal LIKE CONCAT('%', #{pConstrVal}, '%')
AND ConstrValDesc LIKE CONCAT('%', #{pConstrValDesc}, '%')
ORDER BY ${sidx} ${sord}
ORDER BY ConstrValSeq, ConstrValDesc

mapper.delete:
DELETE FROM tCodConstrVal
WHERE ConstrCode = #{constrCode}
AND   ConstrVal  = #{constrVal}
